// Implementation for Bls12-381.
use group::cofactor::CofactorGroup;
use midnight_curves::{Fp as BlsBase, G1Affine, G1Projective};

impl CircuitCurve for G1Projective {
    type Base = BlsBase;
    type ScalarField = <Self as Group>::Scalar;
    type CryptographicGroup = G1Projective;

    // BLS12-381 G1 cofactor.
    const COFACTOR: u128 = 0x396c8c005555e1568c00aaab0000aaab;
    const NUM_BITS_SUBGROUP: u32 = 255;

    fn coordinates(&self) -> Option<(Self::Base, Self::Base)> {
        if self.is_identity().into() {
            return None;
        }
        let affine = self.to_affine();
        Some((affine.x(), affine.y()))
    }

    fn from_xy(x: Self::Base, y: Self::Base) -> Option<Self> {
        // Check the (short) Weierstrass curve equation: y² = x³ + Ax + B
        // The underlying `CurveAffine::from_xy` handles the identity coordinates
        // without errors via a short-circuit check.
        let a = <Self as WeierstrassCurve>::A;
        let b = <Self as WeierstrassCurve>::B;
        if y.square() != x.square() * x + a * x + b {
            return None;
        }
        <G1Affine as CurveAffine>::from_xy(x, y).into_option().map(|p| p.into())
    }

    fn try_into_subgroup(self) -> Option<Self::CryptographicGroup> {
        Some(self)
    }
}

impl WeierstrassCurve for G1Projective {
    const A: Self::Base = midnight_curves::A;
    const B: Self::Base = midnight_curves::B;

pub fn assign(
    layouter: &mut impl Layouter<S::F>,
    curve_chip: &S::CurveChip,
    scalar_chip: &S::ScalarChip,
    len: usize,
    fixed_base_names: &[String],
    msm_value: Value<Msm<S>>,
) -> Result<Self, Error> {
    let bases_val = msm_value.as_ref().map(|msm| msm.bases.clone()).transpose_vec(len);

    let scalars_val = msm_value.as_ref().map(|msm| msm.scalars.clone()).transpose_vec(len);

    let fixed_base_scalars_val = msm_value
        .as_ref()
        .map(|msm| {
            // We only use the keys inside the Value to iterate over it in the right order,
            // these are then discarded.
            msm.fixed_base_scalars.iter().map(|s| *s.1).collect::<Vec<_>>()
        })
        .transpose_vec(fixed_base_names.len());

    // Sort the fixed_base_names to ensure consistency with the BTreeMap.
    let mut fixed_base_names = fixed_base_names.to_vec();
    fixed_base_names.sort();

    let bases = bases_val
        .iter()
        .map(|p| S::assign_without_subgroup_check(layouter, curve_chip, *p))
        .collect::<Result<Vec<_>, Error>>()?;
    let scalars = assign_bounded_scalars(layouter, scalar_chip, &scalars_val)?;
    let fixed_base_scalars: BTreeMap<String, AssignedBoundedScalar<S::F>> = {
        let scalars = assign_bounded_scalars(layouter, scalar_chip, &fixed_base_scalars_val)?;
        fixed_base_names.iter().cloned().zip(scalars).collect()
    };

    Ok(AssignedMsm {
        scalars,
        bases,
        fixed_base_scalars,
    })

