#[cfg(feature = "dev-curves")]
impl SelfEmulation for BnEmulation {

/// curve and lies in the prime-order subgroup.
///
/// If you deliberately need to skip the subgroup check, use
/// [`EccInstructions::assign_without_subgroup_check`] instead.
fn assign(
    &self,
    layouter: &mut impl Layouter<F>,
    value: Value<C::CryptographicGroup>,
) -> Result<AssignedForeignPoint<F, C, B>, Error> {
    if C::COFACTOR > 1 {
        let cofactor = C::ScalarField::from_u128(C::COFACTOR);
        // Exhibit a cofactor-root Q and assert h * Q = p in-circuit.
        // This guarantees that p ∈ C::CryptographicGroup = h · E(Fp).
        let cofactor_root = self.assign_without_subgroup_check(
            layouter,
            value.map(|point| point * cofactor.invert().unwrap()),
        )?;
        self.mul_by_constant(layouter, cofactor, &cofactor_root)
    } else {
        self.assign_without_subgroup_check(layouter, value)
    }
}

    fn assign_as_public_input(
        &self,
        layouter: &mut impl Layouter<F>,
        value: Value<C::CryptographicGroup>,
    ) -> Result<AssignedForeignPoint<F, C, B>, Error> {
        // Given our optimized way of constraining a point as public input, we
        // cannot optimize the direct assignment as PI. We just compose `assign`
        // with `constrain_as_public_input`.
        let point = self.assign_without_subgroup_check(layouter, value)?;
        self.constrain_as_public_input(layouter, &point)?;
        Ok(point)
    }
}

    fn is_zero(
        &self,
        _layouter: &mut impl Layouter<F>,
        p: &AssignedForeignPoint<F, C, B>,
    ) -> Result<AssignedBit<F>, Error> {
        Ok(p.is_id.clone())
    }
}

impl<F, C, B, S, N> ControlFlowInstructions<F, AssignedForeignPoint<F, C, B>>
    for ForeignWeierstrassEccChip<F, C, B, S, N>
where
    F: CircuitField,
    C: WeierstrassCurve,
    B: FieldEmulationParams<F, C::Base>,
    S: ScalarFieldInstructions<F>,
    S::Scalar: InnerValue<Element = C::ScalarField>,
    N: NativeInstructions<F>,
{
    /// Returns `p` if `cond = 1` and `q` otherwise.
    fn select(
        &self,
        layouter: &mut impl Layouter<F>,
        cond: &AssignedBit<F>,
        p: &AssignedForeignPoint<F, C, B>,
        q: &AssignedForeignPoint<F, C, B>,
    ) -> Result<AssignedForeignPoint<F, C, B>, Error> {
        let point = p.point.zip(q.point).zip(cond.value()).map(|((p, q), b)| if b { p } else { q });
        let is_id = self.native_gadget.select(layouter, cond, &p.is_id, &q.is_id)?;
        let x = self.base_field_chip().select(layouter, cond, &p.x, &q.x)?;
        let y = self.base_field_chip().select(layouter, cond, &p.y, &q.y)?;
        Ok(AssignedForeignPoint::<F, C, B> { point, is_id, x, y })
    }
}

impl<F, C, B, S, N> EccInstructions<F, C> for ForeignWeierstrassEccChip<F, C, B, S, N>
where

fn mul_by_constant(
    &self,
    layouter: &mut impl Layouter<F>,
    scalar: C::ScalarField,
    base: &Self::Point,
) -> Result<Self::Point, Error> {
    // We leverage the existing implementation for `mul_by_u128` when the scalar has
    // 128 bits. Otherwise, we just default to a standard multiplication by an
    // assigned-fixed scalar.
    let scalar_as_big = scalar.to_biguint();
    if scalar_as_big.bits() <= 128 {
        let n = scalar_as_big
            .to_u64_digits()
            .iter()
            .rev()
            .fold(0u128, |acc, limb| (acc << 64) | (*limb as u128));

        // `mul_by_u128` is incomplete (it cannot take the identity).
        // Change the base in case it is the identity and then change
        // the result back when necessary.
        let id = self.assign_fixed(layouter, C::CryptographicGroup::identity())?;
        let g = self.assign_fixed(layouter, C::CryptographicGroup::generator())?;
        let p = self.select(layouter, &base.is_id, &g, base)?;
        let r = self.mul_by_u128(layouter, n, &p)?;
        return self.select(layouter, &base.is_id, &id, &r);
    }

fn assign_without_subgroup_check(
    &self,
    layouter: &mut impl Layouter<F>,
    value: Value<C::CryptographicGroup>,
) -> Result<Self::Point, Error> {
    let p = self.assign_point_unchecked(layouter, value)?;
    let is_not_id = self.native_gadget.not(layouter, &p.is_id)?;
    on_curve::assert_is_on_curve::<F, C, B, N>(
        layouter,
        &is_not_id,
        &p.x,
        &p.y,
        self.base_field_chip(),
        &self.config.on_curve_config,
    )?;
    Ok(p)
}

/// The point is not asserted (with constraints) to be on the curve.
/// The point may be the identity.
fn assign_point_unchecked(
    &self,
    layouter: &mut impl Layouter<F>,
    p: Value<C::CryptographicGroup>,
) -> Result<AssignedForeignPoint<F, C, B>, Error> {
    let values = p.map(|p| {
        if C::CryptographicGroup::is_identity(&p).into() {
            (C::Base::ZERO, C::Base::ZERO, true)
        } else {
            let coordinates =
                p.into().coordinates().expect("assign_point_unchecked: invalid point given");
            (coordinates.0, coordinates.1, false)
        }
    });
    let x = self.base_field_chip().assign(layouter, values.map(|v| v.0))?;
    let y = self.base_field_chip().assign(layouter, values.map(|v| v.1))?;
    let is_id = self.native_gadget.assign(layouter, values.map(|v| v.2))?;
    let p = AssignedForeignPoint::<F, C, B> {
        point: p,
        is_id,
        x,
        y,
    };
    Ok(p)
}

/// Given `p` and `q`, returns `p + q`.
///
/// This function is incomplete because it is not designed to deal with

fn mul_by_u128(
    &self,
    layouter: &mut impl Layouter<F>,
    n: u128,
    p: &AssignedForeignPoint<F, C, B>,
) -> Result<AssignedForeignPoint<F, C, B>, Error> {
    if n == 0 {
        return self.assign_fixed(layouter, C::CryptographicGroup::identity());
    };

    // Assert that (n : u128) is smaller than ORDER / 2.
    // This condition allows us to use incomplete addition in the loop below.
    assert!(129 < C::ScalarField::NUM_BITS);

    // Double-and-add (starting from the LSB)

    let mut res = None;

    // tmp will encode (2^i p) on every iteration, to be added (selectively) to res.
    let mut tmp = p.clone();

    // We iterate over the bits of n.
    let mut n = n;
    while n > 0 {
        // In order to safetly use [incomplete_add] here, we need to show
        // that these three preconditions are met when res != None:
        //   (1) res != id
        //   (2) tmp != id
        //   (3) res.x != tmp.x   (i.e. res != ±tmp)
        //
        // Note that p != id holds by assumption.
        // Also, note that on the i-th iteration (counting from i = 0),
        // at this point we have:
        //    res := None or Some(k p) with 0 < k < 2^i
        //    tmp := 2^i p
        //
        // (1) & (2) hold because all non-identity points have Scalar.ORDER order by
        //           assumption, and 2^i is smaller than ORDER on every iteration.
        // (3) holds because otherwise we would have k p = ± 2^i p with 0 < k < 2^i.
        //     Thus (k ∓ 2^i) p = id, which means that (k ∓ 2^i) is
        //     a multiple of ORDER, however this is not possible as:
        //        (i) k ∓ 2^i != 0 because 0 < k < 2^i
        //       (ii) k - 2^i > -2^i > -ORDER    (because i < 128 < |ORDER|)
        //      (iii) k + 2^i < 2^(i+1) < ORDER  (because i+1 < 129 < |ORDER|)
        if !n.is_multiple_of(2) {
            res = match res {
                None => Some(tmp.clone()),
                Some(acc) => Some(self.incomplete_add(layouter, &acc, &tmp)?),
            };
        }
        n >>= 1;

        if n > 0 {
            tmp = self.double(layouter, &tmp)?
        }
    }

    Ok(res.unwrap())

    nb_parallel_range_checks: usize,
    max_bit_len: u32,
) -> ((BI, BI), Vec<(BI, BI)>)
where
    F: CircuitField,
    P: FieldEmulationParams<F, C::Base>,
{
    let base = BI::from(2).pow(P::LOG2_BASE);
    let nb_limbs = P::NB_LIMBS;
    let moduli = P::moduli();
    let bs = P::base_powers();
    let bs2 = P::double_base_powers();

    // Use signed representatives of 'a' and 'b' (closest to zero) so that
    // (a+1)*sum_x and (a+b) terms are as small as possible. Critical for
    // curves like P-256 where a = -3 and the unsigned representative q-3
    // would require smaller (and potentially more) auxiliary moduli.
    let a: BI = signed_repr::<C::Base>()(C::A.to_biguint().into());
    let b: BI = signed_repr::<C::Base>()(C::B.to_biguint().into());
    let a_plus_1 = &a + BI::one();
    let a_plus_b = &a + &b;

    // Recall that limbs x_i represent emulated field element 1 + sum_i base^i x_i.
    // Let x := 1 + sum_i base^i x_i
    //     y := 1 + sum_i base^i y_i
    //     z := 1 + sum_i base^i z_i
    //
    // We will have a custom gate enforcing equation:
    //   y^2 - (x * z + a * x + b) = 0  (mod m)
    //
    // So if z equals to x^2 (mod m), this is asserting that (x, y) satisfies the
    // curve equation.
    //
    // Define:
    //   sum_x := sum_i (base^i % m) * x_i
    //   sum_y := sum_i (base^i % m) * y_i
    //   sum_z := sum_i (base^i % m) * z_i
    //  sum_xz := sum_i (sum_j (base^{i+j} % m) * x_i * z_j)
    //  sum_y2 := sum_i (sum_j (base^{i+j} % m) * y_i * y_j)
    //
    // We enforce y^2 = x * z + a * x + b (mod m) with equation:
    //   2 * sum_y + sum_y2 - (sum_xz + sum_z + (a + 1) * sum_x + (a + b)) = k * m

    let limbs_max = vec![&base - BI::one(); nb_limbs as usize];
    let limbs_max2 = vec![(&base - BI::one()).pow(2); (nb_limbs * nb_limbs) as usize];
    let max_sum_x = sum_bigints(&bs, &limbs_max);
    let max_sum_y = max_sum_x.clone();
    let max_sum_z = max_sum_x.clone();
    let max_sum_xz = sum_bigints(&bs2, &limbs_max2);
    let max_sum_y2 = max_sum_xz.clone();

    // expr = 2*sum_y + sum_y2 - sum_xz - sum_z - (a+1)*sum_x - (a+b)
    // The (a+1)*sum_x term can be positive or negative depending on the
    // curve. We use max/min with 0 to route it into the correct bound
    // without branching on the sign of (a+1).
    let expr_min =
        -(&max_sum_xz + &max_sum_z + (&a_plus_1 * &max_sum_x).clone().max(BI::zero()))
            - &a_plus_b;
    let expr_max = BI::from(2) * &max_sum_y + &max_sum_y2
        - (&a_plus_1 * &max_sum_x).min(BI::zero())
        - &a_plus_b;
    let expr_bounds = (expr_min, expr_max);

    let expr_mj_bounds: Vec<_> = moduli
        .iter()
        .map(|mj| {
            let bs_mj = bs.iter().map(|b| b.rem(mj)).collect::<Vec<_>>();
            let bs2_mj = bs2.iter().map(|b| b.rem(mj)).collect::<Vec<_>>();
            let max_sum_x_mj = sum_bigints(&bs_mj, &limbs_max);
            let max_sum_y_mj = max_sum_x_mj.clone();
            let max_sum_z_mj = max_sum_x_mj.clone();
            let max_sum_xz_mj = sum_bigints(&bs2_mj, &limbs_max2);
            let max_sum_y2_mj = max_sum_xz_mj.clone();
            let a_plus_1_mj = signed_mod(&a_plus_1, mj);
            let a_plus_b_mj = signed_mod(&a_plus_b, mj);
            let a1_sum_x_mj = &a_plus_1_mj * &max_sum_x_mj;
            let expr_mj_min =
                -(&max_sum_xz_mj + &max_sum_z_mj + a1_sum_x_mj.clone().max(BI::zero()))
                    - &a_plus_b_mj;
            let expr_mj_max = BI::from(2) * &max_sum_y_mj + &max_sum_y2_mj
                - a1_sum_x_mj.min(BI::zero())
                - &a_plus_b_mj;
            (expr_mj_min, expr_mj_max)
        })
        .collect();
    get_identity_auxiliary_bounds::<F, C::Base>(
        "on_curve",
        &moduli,
        expr_bounds,
        &expr_mj_bounds,
        nb_parallel_range_checks,
        max_bit_len,
    )
}

/// Configures the foreign on_curve gate
pub fn configure<F, P>(
    meta: &mut ConstraintSystem<F>,
    field_chip_config: &FieldChipConfig,
    cond_col: &Column<Advice>,
    nb_parallel_range_checks: usize,
    max_bit_len: u32,
) -> OnCurveConfig<C>
where
    F: CircuitField,
    P: FieldEmulationParams<F, C::Base>,
{
    let m = &C::Base::modulus().to_bigint().unwrap();
    let moduli = P::moduli();
    let bs = P::base_powers();
    let bs2 = P::double_base_powers();

let y2s = ys.clone().map(|ys| pair_wise_prod(&ys, &ys));

let (k_min, u_max) = on_curve_config.u_bounds.clone();

// 2 * sum_y + sum_y2 - (sum_xz + sum_z + (a + 1) * sum_x + (a + b))
// = (u + k_min) * m
let expr = ys.clone().map(|v| BI::from(2) * sum_bigints(&bs, &v) - &a_plus_b)
    + y2s.clone().map(|v| sum_bigints(&bs2, &v))
    - xzs.clone().map(|v| sum_bigints(&bs2, &v))
    - zs.clone().map(|v| sum_bigints(&bs, &v))
    - xs.clone().map(|v| &a_plus_1 * sum_bigints(&bs, &v));
let u = expr.map(|e| compute_u(m, &e, (&k_min, &u_max), cond.value()));

let vs_values =
    moduli.iter().zip(on_curve_config.vs_bounds.iter()).map(|(mj, vj_bounds)| {
        let bs_mj = bs.iter().map(|b| b.rem(mj)).collect::<Vec<_>>();
        let bs2_mj = bs2.iter().map(|b| b.rem(mj)).collect::<Vec<_>>();
        let (lj_min, vj_max) = vj_bounds.clone();

        let a_plus_1_mj = signed_mod(&a_plus_1, mj);
        let a_plus_b_mj = signed_mod(&a_plus_b, mj);

        // 2 * sum_y_mj + sum_y2_mj - (sum_xz_mj + sum_z_mj + signed_mod(a+1, mj)
        // * sum_x_mj + signed_mod(a+b, mj)) - u * (m % mj) - (k_min * m) % mj
        // = (vj + lj_min) * mj
        let expr_mj =
            ys.clone().map(|v| BI::from(2) * sum_bigints(&bs_mj, &v) - &a_plus_b_mj)
                + y2s.clone().map(|v| sum_bigints(&bs2_mj, &v))
                - xzs.clone().map(|v| sum_bigints(&bs2_mj, &v))
                - zs.clone().map(|v| sum_bigints(&bs_mj, &v))
                - xs.clone().map(|v| &a_plus_1_mj * sum_bigints(&bs_mj, &v));
        expr_mj.zip(u.clone()).map(|(e, u)| {
            compute_vj(m, mj, &e, &u, &k_min, (&lj_min, &vj_max), cond.value())
        })

fn assign(
    &self,
    layouter: &mut impl Layouter<F>,
    x: Value<K>,
) -> Result<AssignedField<F, K, P>, Error> {
    let base = BI::from(2).pow(P::LOG2_BASE);
    // We shift the value of x by 1, remember that limbs {xi}_i represent integer
    //   1 + sum_i base^i xi
    let x = x.map(|v| {
        let bi = (v - K::ONE).to_biguint().into();
        bi_to_limbs(P::NB_LIMBS, &base, &bi)
    });

    // Range-check the cells in the range [0, base)
    let x_cells = (0..P::NB_LIMBS)
        .map(|i| x.clone().map(|limbs| bigint_to_fe::<F>(&limbs[i as usize])))
        .zip(well_formed_log2_bounds::<F, K, P>().iter())
        .map(|(xi_value, log2_bound)| {
            self.native_gadget.assign_lower_than_fixed(
                layouter,
                xi_value,
                &(BigUint::one() << *log2_bound),
            )
        })
        .collect::<Result<Vec<_>, Error>>()?;

    Ok(AssignedField::<F, K, P> {
        limb_values: x_cells,
        limb_bounds: well_formed_bounds::<F, K, P>(),

fn assert_equal(
    &self,
    layouter: &mut impl Layouter<F>,
    x: &AssignedField<F, K, P>,
    y: &AssignedField<F, K, P>,
) -> Result<(), Error> {
    // We normalize the x and y before comparing them.
    // Even though field elements may admit several representations in
    // well-formed limbs form, an honest prover will use the canonical one,
    // which allows them to always pass the following equality assertion if the two
    // emulated field elements are indeed equal.
    let x = self.normalize(layouter, x)?;
    let y = self.normalize(layouter, y)?;
    x.limb_values
        .iter()
        .zip(y.limb_values.iter())
        .map(|(xi, yi)| self.native_gadget.assert_equal(layouter, xi, yi))
        .collect::<Result<Vec<_>, _>>()?;

fn assert_equal_to_fixed(
    &self,
    layouter: &mut impl Layouter<F>,
    x: &AssignedField<F, K, P>,
    constant: K,
) -> Result<(), Error> {
    // We normalize x before comparing it to the constant.
    // Even though field elements may admit several representations in
    // well-formed limbs form, an honest prover will use the canonical one,
    // which allows them to always pass the following equality assertion if the x
    // is indeed equal to the given constant.
    let x = self.normalize(layouter, x)?;
    let constant_limbs = {
        let constant = (constant - K::ONE).to_biguint().into();
        let base = BI::from(2).pow(P::LOG2_BASE);
        bi_to_limbs(P::NB_LIMBS, &base, &constant)
    };
    x.limb_values
        .iter()
        .zip(constant_limbs.iter())
        .map(|(xi, ki)| {
            self.native_gadget.assert_equal_to_fixed(layouter, xi, bigint_to_fe::<F>(ki))
        })
        .collect::<Result<Vec<_>, _>>()?;
    Ok(())
}

    fn select(
        &self,
        layouter: &mut impl Layouter<F>,
        cond: &AssignedBit<F>,
        x: &AssignedField<F, K, P>,
        y: &AssignedField<F, K, P>,
    ) -> Result<AssignedField<F, K, P>, Error> {
        let z_limb_values = x
            .limb_values
            .iter()
            .zip(y.limb_values.iter())
            .map(|(xi, yi)| self.native_gadget.select(layouter, cond, xi, yi))
            .collect::<Result<Vec<_>, _>>()?;
        let z_limb_bounds = x
            .limb_bounds
            .iter()
            .zip(y.limb_bounds.iter())
            .map(|(xi_bounds, yi_bounds)| {
                (
                    min(&xi_bounds.0, &yi_bounds.0).clone(),
                    max(&xi_bounds.1, &yi_bounds.1).clone(),
                )
            })
            .collect::<Vec<_>>();
        Ok(AssignedField::<F, K, P> {
            limb_values: z_limb_values,
            limb_bounds: z_limb_bounds,
            _marker: PhantomData,
        })
    }
}

fn add_and_double_mul(
    &self,
    layouter: &mut impl Layouter<F>,
    (a, x): (F, &AssignedNative<F>),
    (b, y): (F, &AssignedNative<F>),
    (c, z): (F, &AssignedNative<F>),
    k: F,
    (m1, m2): (F, F),
) -> Result<AssignedNative<F>, Error> {
    let res_value = x
        .value()
        .zip(y.value())
        .zip(z.value())
        .map(|((x, y), z)| a * x + b * y + c * z + k + m1 * x * y + m2 * x * z);
    layouter.assign_region(
        || "add and double mul",
        |mut region| {
            self.copy_in_row(&mut region, x, &self.config.value_cols[0], 0)?;
            self.copy_in_row(&mut region, y, &self.config.value_cols[1], 0)?;
            self.copy_in_row(&mut region, z, &self.config.value_cols[2], 0)?;
            let res =
                region.assign_advice(|| "res", self.config.value_cols[4], 0, || res_value)?;
            let mut coeffs = [F::ZERO; NB_ARITH_COLS];
            coeffs[0] = a; // coeff of x
            coeffs[1] = b; // coeff of y
            coeffs[2] = c; // coeff of z
            coeffs[4] = -F::ONE; // coeff of res
            self.custom(&mut region, &coeffs, F::ZERO, (m1, m2), k, 0)?;
            Ok(res)
        },

fn assign(
    &self,
    layouter: &mut impl Layouter<F>,
    value: Value<bool>,
) -> Result<AssignedBit<F>, Error> {
    layouter.assign_region(
        || "Assign big",
        |mut region| {
            // Enforce x * x - x = 0
            let b_value = value.map(|b| if b { F::ONE } else { F::ZERO });
            let b = region.assign_advice(|| "b", self.config.value_cols[0], 0, || b_value)?;
            self.copy_in_row(&mut region, &b, &self.config.value_cols[1], 0)?;
            let mut coeffs = [F::ZERO; NB_ARITH_COLS];
            coeffs[0] = -F::ONE; // coeff of x
            self.custom(&mut region, &coeffs, F::ZERO, (F::ONE, F::ZERO), F::ZERO, 0)?;
            Ok(AssignedBit(b))
        },
    )
}

